(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-336":{scenario:{company:"Riverbend Beverages",supervisor:{name:"Trần Minh Châu",role:{vi:"Trưởng phòng Trade Marketing",en:"Trade Marketing Manager"}},ref_code:"TMP-2611",title:{vi:"Trả thưởng theo kệ thật, không theo phiếu đăng ký.",en:"Pay for the real shelf, not the sign-up form."},brief:{vi:"Bạn quyết toán chương trình trưng bày quý IV TMP-2611 cho tạp hóa GT-4417. Nhân viên bán hàng đăng ký gói DP-A, nhưng ảnh chấm điểm cho thấy cửa hàng chỉ có 9 mặt trưng bày (facing) và không có kệ riêng. Kết quả chấm điểm: tháng 10 đạt, tháng 11 không đạt (hết hàng 2 SKU chủ lực), tháng 12 đạt. Đối chiếu bản quyết toán nháp với biên bản chấm điểm, sửa gói trưng bày và tiền thưởng (nghìn đồng), rồi lập báo cáo có căn cứ.",en:"You are settling Q4 display program TMP-2611 for grocery outlet GT-4417. The sales rep registered package DP-A, but the audit photos show only 9 facings and no dedicated rack. Audit results: October passed, November failed (2 core SKUs out of stock), December passed. Compare the draft settlement with the audit record, correct the display package and the reward (thousand VND), then write an evidence-based report."},reference_title:{vi:"Biên bản chấm điểm trưng bày đã duyệt · TMP-2611",en:"Approved display audit record · TMP-2611"},fields:[{id:"DISPLAY_PKG",label:{vi:"Gói trưng bày được quyết toán",en:"Settled display package"},initial:"DP-A",expected:"DP-B",choices:["DP-A","DP-B","DP-C"],reference:"Kết quả chấm điểm quý IV",hint:{vi:"Gói xét theo kệ thực tế: DP-A cần từ 12 facing và kệ riêng, DP-B từ 8 facing, DP-C từ 4 facing.",en:"The package follows the actual shelf: DP-A needs 12+ facings and a rack, DP-B 8+ facings, DP-C 4+ facings."}},{id:"REWARD_K",label:{vi:"Tiền thưởng trưng bày (nghìn đồng)",en:"Display reward (thousand VND)"},initial:"1500",expected:"700",reference:"Bảng mức thưởng & tháng đạt",ref_value:{vi:"Mức mô phỏng: DP-A 500, DP-B 350, DP-C 200 nghìn đồng/tháng; số tháng đạt chuẩn 2/3",en:"Training rates: DP-A 500, DP-B 350, DP-C 200 thousand VND/month; months passed 2/3"},hint:{vi:"Chỉ nhân mức thưởng với số tháng có biên bản chấm điểm đạt, không nhân với thời hạn chương trình.",en:"Multiply the rate only by months with a passed audit, not by the program length."}}],sop32:{vi:"Thưởng trưng bày = mức thưởng của gói đạt thực tế x số tháng có biên bản chấm điểm đạt; tháng không đạt không chi, không chụp bù (mức thưởng là số liệu mô phỏng).",en:"Display reward = rate of the package actually achieved x number of months with a passed audit; failed months are not paid and never re-shot (rates are training data)."},context:{label:"DMS / TMP-2611 · GT-4417",metrics:[{label:{vi:"Facing thực tế",en:"Actual facings"},value:"9"},{label:{vi:"Tháng đạt chuẩn",en:"Months passed"},value:"2/3"},{label:{vi:"Gói đã đăng ký",en:"Registered package"},value:"DP-A"}]},crisis:{vi:"Giám sát bán hàng nhắn: “Cứ quyết toán đủ DP-A ba tháng, chủ tiệm là khách lớn, cắt thưởng là họ chuyển kệ cho đối thủ. Ảnh tháng 11 để anh chụp bù rồi gửi em.”",en:"The sales supervisor messages you: “Just settle DP-A for all three months, the owner is a big customer and will give the shelf to a competitor if we cut. I will re-shoot November photos and send them.”"},options:{safe:{vi:"Quyết toán DP-B cho 2 tháng đạt theo biên bản, từ chối ảnh chụp bù, báo trưởng phòng Trade Marketing và đề xuất hỗ trợ cửa hàng nâng lên DP-A từ kỳ sau.",en:"Settle DP-B for the 2 passed months per the audit, refuse re-shot photos, inform the Trade Marketing Manager and offer to help the outlet reach DP-A next cycle."},shortcut:{vi:"Chi đủ DP-A ba tháng để giữ quan hệ với chủ tiệm, dùng ảnh chụp bù làm chứng từ.",en:"Pay DP-A for all three months to keep the owner happy and file the re-shot photos as evidence."},wait:{vi:"Treo hồ sơ quyết toán đến khi giám sát và chủ tiệm tự thống nhất với nhau.",en:"Hold the settlement until the supervisor and the owner agree between themselves."}},questions:{vi:["Vì sao cửa hàng GT-4417 chỉ được quyết toán DP-B và 700 nghìn đồng? Dữ liệu chấm điểm nào chứng minh?","Nếu chấp nhận ảnh chụp bù tháng 11, công ty gặp rủi ro gì về kiểm soát chi phí và gian lận chứng từ?"],en:["Why is outlet GT-4417 settled at DP-B and 700 thousand VND only? Which audit data proves it?","If the re-shot November photos were accepted, what cost-control and document-fraud risks would the company face?"]},hints:{vi:["Đặt phiếu đăng ký cạnh biên bản chấm điểm và đánh dấu dòng gói trưng bày đang lệch.","Theo SOP mục 3.2, chỉ đếm các tháng có kết quả chấm điểm đạt khi tính thưởng.","Đọc SOP mục 4.2: chứng từ trưng bày phải do người chấm điểm độc lập chụp đúng kỳ, mọi yêu cầu chụp bù phải báo cáo."],en:["Put the sign-up form next to the audit record and flag the display package line that differs.","Per SOP 3.2, count only months with a passed audit when computing the reward.","Read SOP 4.2: display evidence must be shot in-period by an independent auditor and any re-shoot request must be escalated."]}},learning:{summary:{vi:"Chuyên viên Trade Marketing & Trưng bày điểm bán biến chiến lược thương hiệu thành hành động tại kệ: thiết kế chương trình trưng bày, khuyến mại kênh, vật phẩm quảng cáo tại điểm bán (POSM) và tiêu chuẩn cửa hàng hoàn hảo cho kênh truyền thống (GT) và hiện đại (MT). Nghề đòi hỏi hiểu người mua sắm, tính hiệu quả đầu tư từng đồng ngân sách trade và kiểm soát chặt chứng từ chấm điểm để tiền thưởng đến đúng điểm bán đạt chuẩn.",en:"A Trade Marketing & Merchandising Executive turns brand strategy into action at the shelf: designing display programs, channel promotions, point-of-sale materials (POSM) and perfect store standards for general trade (GT) and modern trade (MT). The role requires shopper understanding, return-on-investment thinking for every trade budget unit and tight control of audit evidence so rewards reach only compliant outlets."},responsibilities:{vi:["Thiết kế chương trình trưng bày, khuyến mại kênh và cơ chế thưởng theo phân hạng điểm bán.","Xây dựng planogram, tiêu chuẩn cửa hàng hoàn hảo và hướng dẫn đội bán hàng triển khai.","Lập kế hoạch sản xuất, phân bổ và kiểm soát vật phẩm POSM theo từng khu vực.","Tổ chức chấm điểm trưng bày bằng ảnh, đối chiếu dữ liệu và quyết toán thưởng cho điểm bán.","Đo hiệu quả chương trình (sản lượng tăng thêm, ROI) và đề xuất tối ưu cho kỳ sau."],en:["Design display programs, channel promotions and reward mechanics by outlet tier.","Build planograms and perfect store standards and coach the sales force on execution.","Plan production, allocation and control of POSM for each region.","Run photo-based display audits, reconcile data and settle outlet rewards.","Measure program results (incremental volume, ROI) and propose improvements for the next cycle."]},competencies:[{name:{vi:"Thấu hiểu người mua sắm",en:"Shopper insight"},desc:{vi:"Hiểu hành trình mua tại điểm bán, vị trí kệ, ngang tầm mắt và yếu tố kích hoạt mua ngẫu hứng.",en:"Understand the in-store path to purchase, shelf positions, eye level and impulse triggers."}},{name:{vi:"Thiết kế cơ chế trade",en:"Trade mechanics design"},desc:{vi:"Xây cơ chế thưởng, chiết khấu, trưng bày có điều kiện đo được và phù hợp phân hạng điểm bán.",en:"Build reward, discount and display mechanics with measurable conditions that fit outlet tiers."}},{name:{vi:"Phân tích hiệu quả",en:"Effectiveness analysis"},desc:{vi:"Tách sản lượng nền và sản lượng tăng thêm để tính ROI thực của từng chương trình.",en:"Separate baseline and incremental volume to compute the true ROI of each program."}},{name:{vi:"Kiểm soát chứng từ",en:"Evidence control"},desc:{vi:"Đối chiếu ảnh chấm điểm, dữ liệu DMS và đơn hàng để chống chi sai, chi khống.",en:"Reconcile audit photos, DMS data and orders to prevent wrong or fictitious payouts."}},{name:{vi:"Phối hợp liên phòng ban",en:"Cross-functional coordination"},desc:{vi:"Làm việc với Brand, Sales, Tài chính, nhà cung cấp POSM và đơn vị chấm điểm độc lập.",en:"Work with Brand, Sales, Finance, POSM suppliers and independent audit vendors."}}],knowledge:{vi:["Luật Thương mại số 36/2005/QH11 và Nghị định 81/2018/NĐ-CP về xúc tiến thương mại (khuyến mại, trưng bày, hội chợ).","Cấu trúc kênh phân phối GT, MT, kênh tiêu dùng tại chỗ và vai trò nhà phân phối.","Nguyên tắc trưng bày: planogram, khối thương hiệu, ngang tầm mắt, FIFO, tỷ lệ chiếm kệ (share of shelf).","Chỉ số phân phối: độ phủ số (numeric distribution), độ phủ có trọng số (weighted distribution), tỷ lệ hết hàng.","Đánh giá hiệu quả khuyến mại: sản lượng nền, sản lượng tăng thêm, ROI và chi phí trade trên doanh thu."],en:["Commercial Law No. 36/2005/QH11 and Decree 81/2018/ND-CP on trade promotion (promotions, displays, fairs).","Channel structure of GT, MT, on-premise and the distributor's role.","Merchandising principles: planogram, brand blocking, eye level, FIFO, share of shelf.","Distribution metrics: numeric distribution, weighted distribution, out-of-stock rate.","Promotion evaluation: baseline volume, incremental volume, ROI and trade spend to revenue."]},tools:["DMS (Distributor Management System)","Ứng dụng chấm điểm trưng bày bằng ảnh","Phần mềm thiết kế planogram","Microsoft Excel / Power BI","Bản đồ tuyến bán hàng (route map)"],kpis:{vi:["Tỷ lệ điểm bán đạt chuẩn trưng bày theo chấm điểm độc lập.","Tỷ lệ chiếm kệ và tỷ lệ hết hàng tại điểm bán trọng điểm.","ROI chương trình trade dựa trên sản lượng tăng thêm.","Tỷ lệ quyết toán sai hoặc thiếu chứng từ (mục tiêu bằng 0)."],en:["Share of outlets meeting display standards in independent audits.","Share of shelf and out-of-stock rate at key outlets.","Trade program ROI based on incremental volume.","Rate of wrong or unsupported settlements (target zero)."]},day:[{time:"08:00",vi:"Xem bảng điều khiển chấm điểm hôm qua, lọc điểm bán không đạt và hết hàng.",en:"Review yesterday's audit dashboard and filter failed and out-of-stock outlets."},{time:"09:30",vi:"Đi thị trường cùng giám sát bán hàng, kiểm tra planogram tại 6 cửa hàng trọng điểm.",en:"Visit the market with a sales supervisor and check planograms at 6 key outlets."},{time:"13:30",vi:"Đối chiếu ảnh chấm điểm với dữ liệu DMS, lập bảng quyết toán thưởng trưng bày.",en:"Match audit photos with DMS data and prepare the display reward settlement."},{time:"15:30",vi:"Họp Brand và Tài chính về ngân sách POSM và cơ chế chương trình quý tới.",en:"Meet Brand and Finance on POSM budget and next quarter's program mechanics."},{time:"17:00",vi:"Cập nhật báo cáo ROI chương trình và gửi danh sách điểm bán cần hỗ trợ.",en:"Update the program ROI report and send the list of outlets needing support."}],mistakes:{vi:["Trả thưởng theo gói đăng ký thay vì kết quả chấm điểm thực tế tại kệ.","Tính ROI trên toàn bộ doanh số thay vì sản lượng tăng thêm so với nền.","Chấp nhận ảnh chụp bù, ảnh cũ hoặc ảnh do người hưởng lợi tự chụp làm chứng từ."],en:["Paying by the registered package instead of the actual audited shelf.","Computing ROI on total sales instead of incremental volume over baseline.","Accepting re-shot, old or self-taken photos from beneficiaries as evidence."]},career:[{vi:"Nhân viên trưng bày (merchandiser)",en:"Merchandiser"},{vi:"Chuyên viên Trade Marketing",en:"Trade Marketing Executive"},{vi:"Quản lý Trade Marketing kênh / khu vực",en:"Channel / Regional Trade Marketing Manager"},{vi:"Giám đốc Trade Marketing & Phát triển kênh",en:"Head of Trade Marketing & Channel Development"}],glossary:[{term:"Facing",vi:"Một mặt sản phẩm quay ra phía người mua ở hàng đầu tiên của kệ, đơn vị đếm mức độ hiện diện.",en:"One product face turned toward shoppers on the front row of a shelf, the unit of shelf presence."},{term:"Planogram",vi:"Sơ đồ quy định vị trí, số facing và thứ tự sản phẩm trên kệ.",en:"A diagram that defines product positions, facings and order on the shelf."},{term:"POSM",vi:"Vật phẩm quảng cáo tại điểm bán như kệ, wobbler, poster, tủ mát mang thương hiệu.",en:"Point-of-sale materials such as racks, wobblers, posters and branded coolers."},{term:"Share of shelf",vi:"Tỷ lệ chiều dài kệ hoặc số facing của thương hiệu trên tổng ngành hàng tại điểm bán.",en:"The brand's share of shelf length or facings within the category at an outlet."},{term:"GT / MT",vi:"Kênh truyền thống (tạp hóa, chợ) và kênh hiện đại (siêu thị, cửa hàng tiện lợi).",en:"General trade (groceries, wet markets) and modern trade (supermarkets, convenience stores)."}],quiz:[{q:{vi:"Cửa hàng đăng ký gói cao nhưng chấm điểm chỉ đạt gói thấp hơn. Quyết toán theo căn cứ nào?",en:"An outlet registered a top package but its audit meets only a lower one. What is the settlement basis?"},options:{vi:["Gói đã đăng ký","Kết quả chấm điểm thực tế","Đề xuất của giám sát bán hàng","Doanh số tháng cao nhất"],en:["The registered package","The actual audit result","The sales supervisor's proposal","The best month's sales"]},answer:1,explain:{vi:"Thưởng trưng bày trả cho kệ thực tế đạt chuẩn, căn cứ là biên bản chấm điểm độc lập đúng kỳ.",en:"Display rewards pay for the shelf actually achieved, evidenced by an independent in-period audit."}},{q:{vi:"Chương trình tạo doanh số 900 thùng, sản lượng nền là 700 thùng, chi phí tương đương 100 thùng. Sản lượng tăng thêm là bao nhiêu?",en:"A program delivers 900 cases, baseline is 700 cases and cost equals 100 cases. What is the incremental volume?"},options:{vi:["900 thùng","800 thùng","100 thùng","200 thùng"],en:["900 cases","800 cases","100 cases","200 cases"]},answer:3,explain:{vi:"Sản lượng tăng thêm = 900 - 700 = 200 thùng; ROI phải tính trên phần tăng thêm này.",en:"Incremental volume = 900 - 700 = 200 cases; ROI must be computed on this increment."}},{q:{vi:"Vị trí nào trên kệ thường có khả năng được người mua chú ý nhất?",en:"Which shelf position usually gets the most shopper attention?"},options:{vi:["Ngang tầm mắt","Sát sàn","Trên cùng sát trần","Sau quầy thu ngân, khuất tầm nhìn"],en:["Eye level","Floor level","Top shelf near the ceiling","Behind the counter, out of sight"]},answer:0,explain:{vi:"Vùng ngang tầm mắt được nhìn thấy nhiều nhất nên thường dành cho sản phẩm chủ lực.",en:"The eye-level zone is seen most, so it is usually reserved for core products."}},{q:{vi:"Giám sát bán hàng đề nghị chụp bù ảnh tháng không đạt để chi đủ thưởng. Bạn làm gì?",en:"A sales supervisor offers to re-shoot photos for a failed month to pay the full reward. What do you do?"},options:{vi:["Nhận ảnh chụp bù vì khách hàng quan trọng","Chi đủ rồi trừ vào kỳ sau","Từ chối, quyết toán đúng biên bản và báo cấp trên","Xóa tháng không đạt khỏi hệ thống"],en:["Accept the re-shoot because the customer matters","Pay in full and deduct next cycle","Refuse, settle per the audit and escalate","Delete the failed month from the system"]},answer:2,explain:{vi:"Ảnh chụp bù là chứng từ không trung thực; phải quyết toán theo biên bản và báo cáo áp lực gian lận.",en:"Re-shot photos are dishonest evidence; settle per the audit and escalate the fraud pressure."}}],tools_en:["DMS (Distributor Management System)","Photo-based display audit app","Planogram design software","Microsoft Excel / Power BI","Sales route map"]}}})})(window.KKR);
